validator:
function validate(input) {
  const [{ Orders = [] }] = input;
  const ids = new Set();
  for (const [id, customer, type] of Orders) {
    if (id === null) return 'Every order needs an order_id.';
    if (ids.has(id)) return `order_id ${id} appears twice in Orders.`;
    if (customer === null) return `Order ${id} needs a customer_id.`;
    if (type !== 0 && type !== 1) return `Order ${id} has order_type ${type}; it must be 0 or 1.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  const customers = small ? 1 + Math.floor(rand() * 4) : 600;
  // Each customer leans towards type 0, type 1 or a mix, so all three situations appear.
  const lean = Array.from({ length: customers + 1 }, () => [0.0, 0.5, 1.0][Math.floor(rand() * 3)]);
  const Orders = [];
  let id = small ? Math.floor(rand() * 5) : 0;
  for (let i = 0; i < count; i++) {
    id += 1 + (small ? Math.floor(rand() * 3) : 0);
    const customer = 1 + Math.floor(rand() * customers);
    Orders.push([id, customer, rand() < lean[customer] ? 1 : 0]);
  }
  return [{ Orders }];
}
